// Copyright (c) 2026 Roshan. All rights reserved.// Proprietary license — see LICENSE file for details.package com.roshan.persona.vision.detectionimport timber.log.Timberimport com.roshan.persona.vision.ocr.BoundingBox/** * NOUS — Real-Time Tracker (Module 6 v4 — Step 6.3). * * Implements **SORT (Simple Online Realtime Tracking)** — the algorithm * specified in strategy v4 §"Architecture → RealTimeTracker". * * ## Why tracking matters * * Object detection alone gives bounding boxes per frame, but doesn't know * that "person in frame 1" and "person in frame 2" are the SAME person. * * Tracking assigns a persistent [trackId] to each detected object, so NOUS can: *  - Say "There's a person walking towards you" (not "There's a person. There's *    a person. There's a person." every frame). *  - Detect when objects enter/leave the scene. *  - Compute trajectories (e.g., "the motorcycle is approaching from your right"). * * ## SORT Algorithm (per strategy v4 §"Architecture") * * ``` * For each new frame: *   1. Get detections from [ObjectDetector] (with bounding boxes + confidence). *   2. Compute IoU (Intersection over Union) between each detection and each *      existing track's last known box. *   3. Match detections to tracks via greedy assignment (highest IoU first). *      - IoU > 0.30 = match (update the track's box + reset miss count). *      - IoU ≤ 0.30 = no match. *   4. Unmatched detections → create new tracks (assign next trackId). *   5. Unmatched tracks → increment miss count (evict after MAX_MISS_COUNT). *   6. Return list of matched detections (with trackIds assigned). * ``` * * ## Privacy (per strategy v4 §"Privacy & Security") * *  - Track histories are bounded (max 10 boxes, FIFO). *  - Tracks are evicted after 30 consecutive misses (~1 second at 30 FPS). *  - Tracker state is RAM-only — never persisted. *  - Track IDs are sequential integers — they carry no identity information. * * ## Testability * * [RealTimeTracker] is a pure class with no Android dependencies — fully * testable without Robolectric. * * @see <a href="docs/strategy/module-6-vision-strategy-v4.md">§Architecture → RealTimeTracker</a> */class RealTimeTracker(    private val iouThreshold: Float = DEFAULT_IOU_THRESHOLD,    private val maxMissCount: Int = DEFAULT_MAX_MISS_COUNT,) {    /** Active tracks (trackId → track). */    private val tracks = mutableMapOf<Int, TrackingTrack>()    /** Next track ID to assign. */    private var nextTrackId: Int = 1    /** Total tracks created (for stats). */    private var totalTracksCreated: Int = 0    /**     * Update the tracker with new detections from the current frame.     *     * @param detections raw detections from [ObjectDetector] (no trackIds yet).     * @param frameTimestampMs when the frame was captured.     * @return list of detections with trackIds assigned (matched + new).     */    fun update(        detections: List<DetectedObject>,        frameTimestampMs: Long,    ): List<DetectedObject> {        if (detections.isEmpty()) {            // No detections — mark all existing tracks as missed.            markAllMissed()            evictLostTracks()            return emptyList()        }        // Compute IoU matrix: detections × existing tracks.        val matches = mutableListOf<Match>()        val trackList = tracks.values.toList()        for ((detIdx, detection) in detections.withIndex()) {            for (track in trackList) {                val lastBox = track.currentBox ?: continue                val iou = iou(detection.boundingBox, lastBox.boundingBox)                if (iou > iouThreshold && detection.classLabel == track.classLabel) {                    matches.add(Match(detIdx, track.trackId, iou))                }            }        }        // Greedy assignment: sort matches by IoU descending, assign in order.        val sortedMatches = matches.sortedByDescending { it.iou }        val matchedDetectionIndices = mutableSetOf<Int>()        val matchedTrackIds = mutableSetOf<Int>()        val result = mutableListOf<DetectedObject>()        for (match in sortedMatches) {            if (match.detIdx in matchedDetectionIndices || match.trackId in matchedTrackIds) {                continue  // Already matched.            }            val detection = detections[match.detIdx]            val track = tracks[match.trackId] ?: continue            // Update the track with the new box.            val updatedTrack = track.update(                box = TrackedBox(                    boundingBox = detection.boundingBox,                    confidence = detection.confidence,                    timestampMs = frameTimestampMs,                ),                frameMs = frameTimestampMs,            )            tracks[match.trackId] = updatedTrack            // Add detection with trackId assigned.            result.add(detection.copy(trackId = match.trackId))            matchedDetectionIndices.add(match.detIdx)            matchedTrackIds.add(match.trackId)        }        // Unmatched detections → create new tracks.        for ((detIdx, detection) in detections.withIndex()) {            if (detIdx in matchedDetectionIndices) continue            val newTrackId = nextTrackId++            val newTrack = TrackingTrack(                trackId = newTrackId,                classLabel = detection.classLabel,                history = listOf(                    TrackedBox(                        boundingBox = detection.boundingBox,                        confidence = detection.confidence,                        timestampMs = frameTimestampMs,                    ),                ),                lastSeenFrameMs = frameTimestampMs,                hitCount = 1,                missCount = 0,            )            tracks[newTrackId] = newTrack            totalTracksCreated++            result.add(detection.copy(trackId = newTrackId))        }        // Unmatched tracks → increment miss count.        for (trackId in tracks.keys.toList()) {            if (trackId !in matchedTrackIds) {                tracks[trackId] = tracks[trackId]?.markMiss() ?: continue            }        }        // Evict lost tracks.        evictLostTracks()        return result    }    /** Mark all existing tracks as missed (called when no detections). */    private fun markAllMissed() {        for (trackId in tracks.keys.toList()) {            tracks[trackId] = tracks[trackId]?.markMiss() ?: return        }    }    /** Evict tracks with miss count > [maxMissCount]. */    private fun evictLostTracks() {        val toEvict = tracks.filter { it.value.shouldEvict }.keys        for (trackId in toEvict) {            tracks.remove(trackId)            Timber.tag(TAG).v("Evicted lost track $trackId.")        }    }    /** Compute IoU (Intersection over Union) of two bounding boxes. */    internal fun iou(a: BoundingBox, b: BoundingBox): Float {        val intersectionLeft = maxOf(a.left, b.left)        val intersectionTop = maxOf(a.top, b.top)        val intersectionRight = minOf(a.right, b.right)        val intersectionBottom = minOf(a.bottom, b.bottom)        val intersectionWidth = (intersectionRight - intersectionLeft).coerceAtLeast(0f)        val intersectionHeight = (intersectionBottom - intersectionTop).coerceAtLeast(0f)        val intersectionArea = intersectionWidth * intersectionHeight        val unionArea = a.area + b.area - intersectionArea        return if (unionArea > 0) intersectionArea / unionArea else 0f    }    /** Get all active tracks. */    fun activeTracks(): List<TrackingTrack> = tracks.values.toList()    /** Get a specific track by ID. */    fun trackById(trackId: Int): TrackingTrack? = tracks[trackId]    /** Get the current track count. */    fun trackCount(): Int = tracks.size    /** Get total tracks created (for stats). */    fun totalTracksCreated(): Int = totalTracksCreated    /** Reset the tracker (clears all tracks). */    fun reset() {        tracks.clear()        nextTrackId = 1        totalTracksCreated = 0        Timber.tag(TAG).d("RealTimeTracker reset.")    }    /** Internal match representation for greedy assignment. */    private data class Match(        val detIdx: Int,        val trackId: Int,        val iou: Float,    )    private companion object {        private const val TAG = "RealTimeTracker"        private const val DEFAULT_IOU_THRESHOLD = 0.30f        private const val DEFAULT_MAX_MISS_COUNT = 30    }}